/** Defaults to exact. In loaded mode total counts rows on the requested page; unknown mode ignores total. */
totalKind?: 'exact' | 'loaded' | 'unknown'
/** Non-exact totals never infer another page from a full loaded page. */
hasNextPage?: boolean
onPageChange: (page: number) => void

export function Pagination({ page, pageSize, total, totalKind = 'exact', hasNextPage, onPageChange, onPageSizeChange, pageSizeOptions = [25, 50, 100] }: PaginationProps) {
  const { t } = useTranslation()
  const { fmtInt } = useNumberFormatting()
  const inputId = useId()
  const configuredOptions = [...new Set((pageSizeOptions ?? []).filter(size => Number.isSafeInteger(size) && size > 0))]
  const safePageSize = Number.isSafeInteger(pageSize) && pageSize > 0 ? pageSize : (configuredOptions[0] ?? 25)
  const safeTotal = Number.isFinite(total) ? Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(total))) : 0
  const totalPages = Math.max(1, Math.ceil(safeTotal / safePageSize))
  const exactTotal = totalKind === 'exact'
  const safePage = Number.isFinite(page) ? Math.min(Math.max(1, Math.floor(page)), exactTotal ? totalPages : Number.MAX_SAFE_INTEGER) : 1
  const canGoNext = safePage < Number.MAX_SAFE_INTEGER && (exactTotal ? safePage < totalPages : hasNextPage === true)
  const start = safeTotal > 0 ? (safePage - 1) * safePageSize + 1 : 0

  start: fmtInt(start), end: fmtInt(Math.min(safePage * safePageSize, safeTotal)), total: fmtInt(safeTotal),
}) : totalKind === 'loaded' ? t('table.filter.loadedRowCount', '{{filtered}} matching / {{loaded}} loaded rows', {
  filtered: fmtInt(safeTotal), loaded: fmtInt(safeTotal),
}) : t('pagination.currentPage', 'Page {{page}} of {{total}}', {
  page: fmtInt(safePage), total: t('common.unknown', 'Unknown'),
})}
